def stage_action_plan(record):
    routes = dict(record.get('allowed_routes', {}))
    requested = str(record.get('requested_action', ''))
    fallback = record.get('preview_route') if record.get('preview') is True else None
    return {'requested': requested, 'route': routes.get(requested), 'fallback': fallback}

def finalize_action_plan(staged):
    route = staged.get('route') or staged.get('fallback')
    decision = 'allowed' if route is not None else 'blocked'
    return {'decision': decision, 'route': route}
